Cartridge::Cartridge(const char* filename, ROMBackend backend)
{
    struct cartridge_header
    {
        char name[4];
        uint8_t PRG_ROM_chunks;
        uint8_t CHR_ROM_chunks;
        uint8_t mapper1;
        uint8_t mapper2;
        uint8_t PRG_RAM_size;
        uint8_t tv_system;
        uint8_t tv_system2;
        char unused[5];
    } header;

    // Load Cartridge ROM
    rom = SD.open(filename, FILE_READ);
    if (!rom) return;

    rom.read((uint8_t*)&header, sizeof(cartridge_header));
    if (header.mapper1 & 0x04) rom.seek(rom.position() + 512);

    mapper_ID = (header.mapper2 & 0xF0) | header.mapper1 >> 4;
    hardware_mirror = (header.mapper1 & 0x01) ? MIRROR::VERTICAL : MIRROR::HORIZONTAL;

    uint8_t number_PRG_banks = 0;
    uint8_t number_CHR_banks = 0;
    // Check file format
    uint8_t file_type = 1;
    // if ((header.mapper2 & 0x0C) == 0x08);
    switch (file_type)
    {
    case 1:
        number_PRG_banks = header.PRG_ROM_chunks;
        number_CHR_banks = header.CHR_ROM_chunks;
        break;
    case 2:
        number_PRG_banks = ((header.PRG_RAM_size & 0x07) << 8) | header.PRG_ROM_chunks;
        number_CHR_banks = ((header.PRG_RAM_size & 0x38) << 8) | header.CHR_ROM_chunks;
        break;

    default: break;
    }

    prg_base = sizeof(cartridge_header) + (header.mapper1 & 0x04 ? 512 : 0);
    chr_base = prg_base + (number_PRG_banks * 16384);

    // Calculate ROM CRC32
    {
        uint8_t buf[4096];
        size_t len;
        rom.seek(prg_base);
        while ((len = rom.read(buf, sizeof(buf))) > 0) { CRC32 = crc32(buf, len, CRC32); }
        CRC32 ^= ~0U;
        LOGF("CRC32: %08lX\n", (unsigned int)CRC32);
    }

    if (backend == ROMBackend::FLASH)
    {
        mappedROM_init(&mROM, this, CRC32, number_PRG_banks, number_CHR_banks);
    }
    createMapper(number_PRG_banks, number_CHR_banks, backend);
    LOGF("Cartridge (Mapper %i) Initialized\n", mapper_ID);
}

