#include "cpu6502.h"

#define EXECUTE(addrmode, instruction)                                                             \
    {                                                                                              \
        additional_cycle1 = addrmode();                                                            \
        additional_cycle2 = instruction();                                                         \
    }

Cpu6502::Cpu6502()
{
    bus.connectCPU(this);
    apu.connectCPU(this);
    apu.connectBus(&bus);
}

