inline uint8_t Cpu6502::Instr_CMP()
{
    uint8_t byte = read(addr_abs);
    uint16_t temp = (uint16_t)A - (uint16_t)byte;
    SET_FLAG(C, A >= byte);
    SET_ZN(temp & 0x00FF);
    return 1;
}

inline uint8_t Cpu6502::Instr_CPX()
