    SET_ZN(temp & 0x00FF);
    return 0;
}

inline uint8_t Cpu6502::Instr_BCC()
{
    if (GET_FLAG(C) == 0)
    {
        cycles++;
        addr_abs = PC + addr_rel;

        if ((addr_abs & 0xFF00) != (PC & 0xFF00)) cycles++;

        PC = addr_abs;
    }
    return 0;
}

inline uint8_t Cpu6502::Instr_BCS()
{
    if (GET_FLAG(C) == 1)
    {
        cycles++;
        addr_abs = PC + addr_rel;

        if ((addr_abs & 0xFF00) != (PC & 0xFF00)) cycles++;

